/**
 * Bird character registry (Fix #6) — maps the six supplied cartoon bird
 * artworks onto the EXISTING projectile roster. Pure data, no Phaser
 * imports: unit-testable like config.js.
 *
 * Geometry contract (generated by scripts/build-birds.mjs, mirrored from
 * public/assets/images/birds/birds-manifest.json):
 *   - each texture is a square, transparent-padded PNG
 *   - the bird's round MAIN BODY is inscribed in a circle of `bodyRadius`
 *     px centered at the texture center (crest / tail / wing protrusions
 *     may extend beyond it — they are visual only)
 *   - `size` is the texture's full width/height
 *
 * Because of that contract, the Matter.js collider for a bird projectile
 * is simply a circle at the texture center with radius `bodyRadius`, and
 * the physics body ends up with EXACTLY PROJECTILE_TYPES[key].radius in
 * world units when displayed at `radius * 2 * size / (2 * bodyRadius)`
 * (see projectileVisual) — identical mass, shape and collision behavior
 * to the old procedural circles, with the artwork overhanging slightly.
 */

/** Bird texture files shipped in public/assets/images/birds/. */
export const BIRD_ASSET_BASE = 'assets/images/birds/';

/**
 * All six birds. `projectileKey` links a bird to an existing projectile
 * type in PROJECTILE_TYPES (config.js) — null means "art asset only, no
 * gameplay role yet" (green).
 */
export const BIRDS = {
  red: {
    id: 'red',
    name: 'Red Bird',
    texture: 'bird-red',
    file: 'red_basic.png',
    size: 274,
    bodyRadius: 80.7,
    projectileKey: 'basic',
    ability: null,
    recommendedDisplay: 54.3
  },
  blue: {
    id: 'blue',
    name: 'Blue Bird',
    texture: 'bird-blue',
    file: 'blue_split.png',
    size: 282,
    bodyRadius: 80.7,
    projectileKey: 'split',
    ability: 'split',
    recommendedDisplay: 59.4
  },
  yellow: {
    id: 'yellow',
    name: 'Yellow Bird',
    texture: 'bird-yellow',
    file: 'yellow_speed.png',
    size: 366,
    bodyRadius: 81.0,
    projectileKey: 'speed',
    ability: 'boost',
    recommendedDisplay: 67.8
  },
  black: {
    id: 'black',
    name: 'Black Bird',
    texture: 'bird-black',
    file: 'black_bomb.png',
    size: 288,
    bodyRadius: 80.7,
    projectileKey: 'bomb',
    ability: 'detonate',
    recommendedDisplay: 60.7
  },
  purple: {
    id: 'purple',
    name: 'Purple Bird',
    texture: 'bird-purple',
    file: 'purple_ice.png',
    size: 286,
    bodyRadius: 80.7,
    projectileKey: 'ice',
    ability: 'freeze',
    recommendedDisplay: 53.2
  },
  green: {
    id: 'green',
    name: 'Green Bird',
    texture: 'bird-green',
    file: 'green_bonus.png',
    size: 288,
    bodyRadius: 81.0,
    projectileKey: null,
    ability: null,
    recommendedDisplay: 53.3
  }
};

/** projectile type key (config.js PROJECTILE_TYPES) → bird id. */
const PROJECTILE_TO_BIRD = Object.values(BIRDS).reduce((acc, b) => {
  if (b.projectileKey) acc[b.projectileKey] = b.id;
  return acc;
}, {});

/** The bird linked to a projectile type, or null (unknown key). */
export function birdForProjectile(typeKey) {
  const id = PROJECTILE_TO_BIRD[typeKey];
  return id ? BIRDS[id] : null;
}

/** Every bird texture to preload: [{ key, file }] (green included). */
export function birdPreloadList() {
  return Object.values(BIRDS).map((b) => ({ key: b.texture, file: b.file }));
}

/**
 * Visual configuration for one projectile instance.
 *
 * Returns { texture, shapeRadius, display, bird }:
 *   texture     Phaser texture key (bird artwork when loaded)
 *   shapeRadius Matter circle radius IN TEXTURE PX — pass straight into
 *               matter.add.image's shape config (the factory then
 *               setDisplaySize(display) which scales body + visual
 *               together, landing the collider on exactly `radius`)
 *   display     square display size in world px
 *   bird        the BIRDS entry, or null when falling back to the
 *               procedural circle texture (headless / missing artwork —
 *               the legacy 'proj-*' keys still work there)
 *
 * @param {string} typeKey projectile type (basic|speed|ice|split|bomb)
 * @param {{exists:(key:string)=>boolean}} textures scene.textures (duck-typed
 *        so plain unit tests can pass { exists: () => false })
 * @param {number} radius collider radius in world px (type radius, or
 *        SPLIT_CHILD.radius for split children)
 * @param {boolean} [child] true for split children (fallback texture key)
 */
export function projectileVisual(typeKey, textures, radius, child = false) {
  const bird = birdForProjectile(typeKey);
  if (bird && textures && typeof textures.exists === 'function' && textures.exists(bird.texture)) {
    return {
      texture: bird.texture,
      shapeRadius: bird.bodyRadius,
      display: (radius * 2 * bird.size) / (2 * bird.bodyRadius),
      bird
    };
  }
  // legacy fallback: procedural circle textures from BootScene
  return {
    texture: child ? 'proj-split-child' : `proj-${typeKey}`,
    shapeRadius: 20, // 40x40 circle texture
    display: radius * 2,
    bird: null
  };
}
